var BTT_UI_LANG = detectInterfaceLang();

function isCjkUiLang(lang) {
  lang = lang || BTT_UI_LANG;
  return lang === 'zh-CN' || lang === 'zh-TW' || lang === 'ja';
}

function t(key, vars) {
  var dict = BTT_I18N[BTT_UI_LANG] || BTT_I18N['en'];
  var val = dict[key];
  if (val === undefined) val = BTT_I18N[BTT_UI_LANG.indexOf('zh') === 0 ? 'zh-CN' : 'en'][key];
  if (val === undefined) val = BTT_I18N['zh-CN'][key];
  if (val === undefined) val = key;
  if (typeof val === 'string' && vars) {
    val = val.replace(/\{(\w+)\}/g, function (m, k) {
      return vars[k] !== undefined ? vars[k] : m;
    });
  }
  return val;
}

function tErr(code) {
  var dict = BTT_I18N[BTT_UI_LANG] || BTT_I18N['en'];
  if (dict && dict.errors && dict.errors[code]) return dict.errors[code];
  var fallback = BTT_I18N[BTT_UI_LANG.indexOf('zh') === 0 ? 'zh-CN' : 'en'].errors || {};
  return fallback[code] || (BTT_I18N['zh-CN'].errors || {})[code] || code;
}

