function langName(code, lang) {
  lang = lang || BTT_UI_LANG;
  var raw = String(code == null ? '' : code);
  if (raw && raw !== 'auto') {
    try {
      if (typeof Intl !== 'undefined' && Intl.DisplayNames) {
        var name = new Intl.DisplayNames([lang], { type: 'language' }).of(raw);
        if (name && name !== raw) return name;
      }
    } catch (e) {}
  }
  var useZh = lang.indexOf('zh') === 0;
  for (var i = 0; i < BTT_LANGUAGES.length; i++) {
    if (BTT_LANGUAGES[i][0].toLowerCase() === raw.toLowerCase()) {
      return useZh ? BTT_LANGUAGES[i][1] : BTT_LANGUAGES[i][2];
    }
  }
  var base = raw.toLowerCase().split('-')[0];
  for (var j = 0; j < BTT_LANGUAGES.length; j++) {
    if (BTT_LANGUAGES[j][0].toLowerCase().split('-')[0] === base) {
      return useZh ? BTT_LANGUAGES[j][1] : BTT_LANGUAGES[j][2];
    }
  }
  return raw;
}

