  '[contenteditable=""]', '[aria-hidden="true"]', '.bt-caption-container',
  '#bilingual-translator-caption-window', '.ytp-caption-window-container',
  '.caption-window',
  '.bilingual-translator-target-wrapper',
  '.bilingual-translator-target-translation-block-wrapper',
  '.bilingual-translator-target-translation-inline-wrapper',
  '[data-bt-skip]', '[data-bt-translation-element-mark="1"]',
  'script', 'style', 'noscript', 'svg', 'math', 'canvas', 'video', 'audio',
  'iframe', 'pre', 'code', 'kbd', 'samp', 'var', 'textarea', 'select',
