  this._observerConnected = false;
  this._pendingCount = 0;
  this._error = null;
  this._rootStateApplied = false;
  this._onlyModeApplied = false;
  /* Arm tab-scoped auto translation only after a manual translation batch
   * actually produces译文 (merged from v1.1.4). */
  this._armTabAfterSuccess = false;
  this._lazyFallbackTimer = null;
  this._lazyFlushTimer = null;
  this._lazyBatch = [];
  this._dynamicTimer = null;
  this._dynamicFirstAt = 0;
  this._dynamicScanning = false;
  this._dynamicQueued = false;
  this._interactionHandler = null;
  this._hiddenObserver = null;
  this._hiddenWatches = null;
  this._hiddenAncestors = null;
  this._attributeObserver = null;
  this._hiddenPruneAt = 0;
  this._followupTimer = null;
  this._errorShown = false;
  this._emptyRetries = 0;
  this._emptyRetryTimer = null;
