  if (!isMeaningfulText(text)) return false;
  if (text.length < minLen) return false;
  if (!/[\p{L}\p{M}]/u.test(text)) return false;
  if (BTT_SKIP_TEXT_RE.test(text.trim())) return false;
  if (settings.skipSameLanguage && looksLikeTargetLanguage(text, this.app.targetLang())) return false;
  var detected = textLanguage(text);
  var never = (settings.siteRules.neverTranslateLanguages || []).map(function (l) { return String(l).toLowerCase().split('-')[0]; });
  if (detected !== 'unknown' && never.indexOf(detected) >= 0) return false;
