  if (!this._titleObserver || this._titleObserverTarget !== titleEl) {
    this._stopTitleObserver();
    try {
      this._titleObserver = new MutationObserver(function () { self._onTitleMutated(); });
      this._titleObserver.observe(titleEl, { childList: true, characterData: true, subtree: true });
      this._titleObserverTarget = titleEl;
    } catch (e2) { this._titleObserver = null; this._titleObserverTarget = null; }
  }
