  var applied = onlyApplied ? record._onlyAppliedValues : null;
  this._muteMutations(function () {
    for (var i = 0; i < nodes.length; i++) {
      try {
        if (!nodes[i] || !nodes[i].isConnected) continue;
        if (applied && nodes[i].nodeValue !== applied[i]) continue;
        nodes[i].nodeValue = record.originalValues[i];
      } catch (e) {}
    }
    try {
      record.el.removeAttribute('data-bt-translation-only');
      record.el.classList.remove('bilingual-translator-target-inner');
      BTT_THEMES.forEach(function (t) {
        if (t.class) record.el.classList.remove('bilingual-translator-target-translation-theme-' + t.class);
      });
    } catch (e2) {}
    record.parts.forEach(function (part) { if (part.outer) part.outer.style.display = ''; });
  });
