    var injected = false;
    try {
      var script = document.createElement('script');
      script.id = 'bt-subtitle-inject';
      script.setAttribute('data-bt-skip', '1');
      script.textContent = BTT_YT_HOOK_SOURCE;
      (document.head || document.documentElement).appendChild(script);
      injected = true;
    } catch (e) {
      // Trusted Types (YouTube) can reject inline script injection.
      warn('early subtitle hook script blocked, trying direct hook', e);
    }
