  'applause', 'applauding', 'clapping', 'cheering', 'cheers\\b', 'booing',
  'whistling', 'sighing', 'sighs\\b', 'exhaling', 'inhaling', 'breathing',
  'coughing', 'sneezing', 'sniffing', 'typing', 'keyboard', 'keys clacking',
  'footsteps', 'knocking', 'door closes', 'door opens', 'door slams',
  'phone ringing', 'ringing', 'beeping', 'buzzer', 'alarm', 'explosion',
